-- Academy: rebuild Yachts Module 4 as "The People & the Client": 15 pages (8 with quick checks, 7 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "The People and the Client", "body": "<p><b>Yacht brokerage is a people business.</b></p><p>You can know yachts. You can understand the market. You can recognise a good specification. You can compare prices. And you can still become a poor broker.</p><p>Why? Because eventually, a yacht transaction comes down to people.</p><p>One person wants to buy. Another wants to sell. Other people advise them. Brokers communicate between them. Captains, lawyers, surveyors, managers, shipyards, financiers and other specialists may become involved. And somewhere in the middle of all that complexity is a client trying to make a very significant decision.</p><p>This is where brokerage becomes personal.</p><p>A yacht may be a €5 million, €10 million or €50 million asset. But the reasons someone wants it can be deeply personal. It may represent family time, freedom, adventure, privacy, a lifelong ambition, a new chapter, a business relationship, or simply something they have always wanted.</p><p>Your job is not to judge those motivations. <b>Your job is to understand them.</b> Because the better you understand the person, the better you can understand the yacht.</p>", "q": "Why can someone who knows yachts, markets and specifications still become a poor broker?", "opts": ["Because knowledge of yachts is not needed in brokerage", "Because a yacht transaction ultimately comes down to people", "Because clients rarely care about specifications", "Because the market matters more than the client"], "correct": 1}, {"heading": "Chapter 1: Who Buys a Yacht?", "body": "<p><b>There is no typical yacht client</b></p><p>This is one of the first assumptions you need to leave behind. Clients come from different industries, countries, backgrounds and stages of life. They may be:</p><p>&bull; entrepreneurs, executives, investors or business owners<br/>&bull; families<br/>&bull; experienced yacht owners or first-time buyers<br/>&bull; professional athletes or entertainers<br/>&bull; companies or family offices<br/>&bull; people who have recently sold a business<br/>&bull; people who have spent years planning for ownership</p><p>Their reasons for buying can be just as different. One client may know exactly what they want. Another may have almost no idea. One may have owned five yachts. Another may never have stepped aboard one. One may focus on technical specifications. Another may care almost entirely about how the yacht feels. The broker must be able to work with all of them.</p><p><b>First-time buyers</b></p><p>A first-time buyer may arrive with strong expectations but limited knowledge. They might say: <em>\"I want a 40-metre yacht with six cabins, a beach club and a helipad.\"</em> That sounds specific. But what does it actually tell you? Perhaps they saw a yacht online. Perhaps a friend owns something similar. Perhaps they believe a larger yacht is automatically better. Perhaps they have never considered crew numbers, operating costs, draft, maintenance or marina access.</p><p>The broker's role is not to embarrass the client for not knowing. It is to <b>educate without making the client feel inexperienced.</b></p><p><b>Experienced owners</b></p><p>An experienced owner may already know what layouts they like, which builders they trust, what they disliked about their previous yacht, how much crew they want, how they use the yacht and which technical compromises they will accept. But experience does not mean the client has no blind spots. They may be emotionally attached to a particular builder, designer or idea. A good broker listens carefully and then tests assumptions respectfully.</p><p><b>The client behind the brief</b></p><p>A client may give you a specification: <em>\"I want a 35-metre motor yacht.\"</em> That is a product requirement. But perhaps the real requirement is: <em>\"I want something my family can use for six weeks every summer without the yacht feeling like a hotel.\"</em></p><p>The second statement tells you far more about size, layout, crew, atmosphere, operating model, guest accommodation, privacy and lifestyle. This is why brokerage starts with listening.</p><p><b>Broker's insight</b></p><p><b>Never confuse what the client asks for with what the client actually needs.</b> The first is information. The second is understanding.</p>", "q": "A client says, \"I want a 35-metre motor yacht.\" What is the broker's task?", "opts": ["To send listings of every 35-metre motor yacht", "To explain why 35 metres is the wrong size", "To ask for their budget and stop there", "To discover the person, the lifestyle and the real need behind the specification"], "correct": 3}, {"heading": "Exercise: The Biggest Yacht I Can Afford", "body": "<p><b>Try it</b></p><p>Take this client statement:</p><p><em>\"I want the biggest yacht I can afford.\"</em></p><p>Write down <b>five questions</b> you would ask before showing them a single yacht. Your objective is not to challenge them. Your objective is to understand what \"biggest\" means to them.</p>", "exercise": {"intro": "Five questions, and what you hope to learn from each.", "groups": [{"title": "My five questions", "section": "services", "fields": [{"key": "big_q1", "label": "Question 1", "type": "short", "min": 10}, {"key": "big_q2", "label": "Question 2", "type": "short", "min": 10}, {"key": "big_q3", "label": "Question 3", "type": "short", "min": 10}, {"key": "big_q4", "label": "Question 4", "type": "short", "min": 10}, {"key": "big_q5", "label": "Question 5", "type": "short", "min": 10}]}, {"title": "What \"biggest\" might mean", "section": "services", "fields": [{"key": "big_means", "label": "What might \"biggest\" actually mean to this client? Give at least three possibilities.", "type": "long", "min": 60}]}]}}, {"heading": "Chapter 2: Discovering What the Client Really Wants", "body": "<p><b>The first conversation matters</b></p><p>A new broker can feel pressure to impress the client. They want to demonstrate knowledge, talk about yachts, and show that they belong in the room. This creates one of the most common beginner mistakes: <b>talking too much.</b> A great first conversation is often less about presenting and more about discovering.</p><p><b>Start broad</b></p><p>Before asking about engines, cabins or cruising speed, understand the life. Useful areas include:</p><p>&bull; <b>Lifestyle:</b> how will the yacht actually be used?<br/>&bull; <b>People:</b> who will be aboard?<br/>&bull; <b>Time:</b> how often will they use it?<br/>&bull; <b>Destinations:</b> where do they want to go?<br/>&bull; <b>Experience:</b> have they owned a yacht before?<br/>&bull; <b>Preferences:</b> what have they seen that they liked or disliked?<br/>&bull; <b>Practicality:</b> what constraints matter?<br/>&bull; <b>Budget:</b> what is the purchase budget?<br/>&bull; <b>Ownership:</b> how do they imagine managing the yacht?<br/>&bull; <b>Future:</b> could their needs change?</p><p><b>Questions that open conversations</b></p><p>Instead of <em>\"How many cabins do you need?\"</em> try: <em>\"Who do you imagine spending the most time aboard with you?\"</em></p><p>Instead of <em>\"Do you want a fast yacht?\"</em> try: <em>\"How important is speed to the way you imagine using the yacht?\"</em></p><p>Instead of <em>\"Do you want a beach club?\"</em> try: <em>\"What do you imagine doing when you're at anchor?\"</em></p><p>The second version gets closer to the reason behind the requirement.</p><p><b>Listen for contradictions</b></p><p>Clients sometimes say things that appear inconsistent. <em>\"We want a very private family yacht,\"</em> then <em>\"we want to host 20 guests regularly.\"</em> Or <em>\"we don't want a large crew,\"</em> then <em>\"we want hotel-level service.\"</em> Or <em>\"we want to cruise everywhere,\"</em> then <em>\"we don't want to spend much time travelling.\"</em></p><p>These are not problems. They are opportunities to ask better questions. The broker's job is to identify the trade-off.</p><p><b>The five levels of listening</b></p><p>When a client speaks, listen for:</p><p>&bull; <b>1. What they say:</b> the literal statement<br/>&bull; <b>2. What they mean:</b> the underlying preference<br/>&bull; <b>3. What they value:</b> the thing that matters most<br/>&bull; <b>4. What they fear:</b> what they want to avoid<br/>&bull; <b>5. What they have not considered:</b> the questions they do not yet know to ask</p><p>This is where professional judgment starts developing.</p><p><b>Broker's insight</b></p><p><b>The best question is often the question that makes the client think.</b></p>", "q": "Which question is better at getting to the reason behind a requirement?", "opts": ["\"What do you imagine doing when you're at anchor?\"", "\"Do you want a beach club?\"", "\"How many cabins do you need?\"", "\"What is your maximum speed requirement?\""], "correct": 0}, {"heading": "Exercise: \"Nothing Too Complicated\"", "body": "<p><b>Try it</b></p><p>Take this statement:</p><p><em>\"I don't want anything too complicated.\"</em></p><p>Write five possible interpretations. For example: they may mean fewer crew, simpler systems, easier ownership, less formal interiors, or that they are nervous about yacht ownership.</p><p>Then write one question that could distinguish between those interpretations.</p>", "exercise": {"intro": "Five interpretations, then a question that separates them.", "groups": [{"title": "Five possible interpretations", "section": "services", "fields": [{"key": "cx_i1", "label": "Interpretation 1", "type": "short", "min": 10}, {"key": "cx_i2", "label": "Interpretation 2", "type": "short", "min": 10}, {"key": "cx_i3", "label": "Interpretation 3", "type": "short", "min": 10}, {"key": "cx_i4", "label": "Interpretation 4", "type": "short", "min": 10}, {"key": "cx_i5", "label": "Interpretation 5", "type": "short", "min": 10}]}, {"title": "The question that tells them apart", "section": "services", "fields": [{"key": "cx_question", "label": "One question that could distinguish between those interpretations", "type": "long", "min": 25}]}]}}, {"heading": "Chapter 3: From Lifestyle to Yacht", "body": "<p><b>The next skill is translation</b></p><p>A client does not normally speak in yacht specifications. They speak in experiences. They say: <em>\"I want to take my children to Greece.\"</em> The broker translates that into questions about range, draft, cruising profile, accommodation, outdoor spaces, tender arrangements, crew, storage, air conditioning, water toys and marina access.</p><p>But the translation must work both ways. You also need to turn specifications back into human consequences.</p><p>&bull; <b>Shallow draft:</b> \"This could give you more flexibility in certain cruising areas.\"<br/>&bull; <b>Large exterior deck:</b> \"You have more space for family meals and time outside.\"<br/>&bull; <b>Five guest cabins:</b> \"You have more flexibility when children, friends or extended family join.\"<br/>&bull; <b>Long range:</b> \"You can spend longer periods away from major ports without needing to refuel as frequently.\"</p><p>The client does not necessarily need the technical definition. They need to understand why it matters to them.</p><p><b>The translation model</b></p><p><b>CLIENT LIFE → NEED → YACHT CHARACTERISTIC → BENEFIT → TRADE-OFF</b></p><p>For example:</p><p>&bull; Client life: family wants to cruise remote Mediterranean anchorages<br/>&bull; Need: access and independence<br/>&bull; Yacht characteristic: appropriate draft and range<br/>&bull; Benefit: greater cruising flexibility<br/>&bull; Trade-off: the yacht may involve compromises elsewhere, such as interior volume, speed or tankage</p><p>That last step matters. A professional broker does not present only benefits. They explain compromises.</p>", "q": "Why must a professional broker explain trade-offs, not only benefits?", "opts": ["Trade-offs help lower the asking price", "Clients prefer hearing about problems first", "Every yacht characteristic involves compromises elsewhere, and presenting only benefits is incomplete", "Benefits are never real without a trade-off"], "correct": 2}, {"heading": "Exercise: Translate the Lifestyle", "body": "<p><b>Try it</b></p><p>Translate these statements into potential yacht requirements.</p><p><b>Client A:</b> \"We spend most of our time outside.\"</p><p><b>Client B:</b> \"My children and their friends will probably come with us.\"</p><p><b>Client C:</b> \"We don't want to spend every holiday moving between marinas.\"</p><p><b>Client D:</b> \"I want the yacht to feel elegant but not formal.\"</p><p>For each, identify the underlying need, possible yacht characteristics, and one trade-off or question you would investigate.</p>", "exercise": {"intro": "Use the translation model: client life, need, yacht characteristic, benefit, trade-off.", "groups": [{"title": "Client A: \"We spend most of our time outside.\"", "section": "services", "fields": [{"key": "ta_need", "label": "Client A: the underlying need", "type": "long", "min": 15}, {"key": "ta_chars", "label": "Client A: possible yacht characteristics", "type": "long", "min": 15}, {"key": "ta_trade", "label": "Client A: one trade-off or question you would investigate", "type": "long", "min": 15}]}, {"title": "Client B: \"My children and their friends will probably come with us.\"", "section": "services", "fields": [{"key": "tb_need", "label": "Client B: the underlying need", "type": "long", "min": 15}, {"key": "tb_chars", "label": "Client B: possible yacht characteristics", "type": "long", "min": 15}, {"key": "tb_trade", "label": "Client B: one trade-off or question you would investigate", "type": "long", "min": 15}]}, {"title": "Client C: \"We don't want to spend every holiday moving between marinas.\"", "section": "services", "fields": [{"key": "tc_need", "label": "Client C: the underlying need", "type": "long", "min": 15}, {"key": "tc_chars", "label": "Client C: possible yacht characteristics", "type": "long", "min": 15}, {"key": "tc_trade", "label": "Client C: one trade-off or question you would investigate", "type": "long", "min": 15}]}, {"title": "Client D: \"I want the yacht to feel elegant but not formal.\"", "section": "services", "fields": [{"key": "td_need", "label": "Client D: the underlying need", "type": "long", "min": 15}, {"key": "td_chars", "label": "Client D: possible yacht characteristics", "type": "long", "min": 15}, {"key": "td_trade", "label": "Client D: one trade-off or question you would investigate", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 4: Trust, Discretion and Relationships", "body": "<p><b>Why would a client trust you?</b></p><p>Think about what a yacht broker may learn: a client's budget, family circumstances, travel plans, ownership preferences, business interests, personal preferences, frustrations, negotiation position, and plans for buying or selling. Some of that information may be highly private. The client needs confidence that the broker will handle it professionally. That makes trust one of the most valuable assets in brokerage.</p><p><b>Discretion is not a marketing phrase</b></p><p>A client may tell you: <em>\"I don't want anyone to know we're looking.\"</em> That is not an invitation to tell three colleagues over lunch. A broker must understand the difference between information that helps the transaction, information that belongs to the client, information that can legitimately be shared, and information that requires permission. Professional discretion is part of the job.</p><p><b>Trust is built through small actions</b></p><p>Clients notice whether you call when you said you would, admit when you do not know something, correct mistakes, remember important details, prepare properly, protect confidential information, avoid unnecessary pressure, give bad news honestly, follow through and respect their time.</p><p>Trust is rarely created by one impressive presentation. It is built through repeated evidence.</p><p><b>Relationships are an asset</b></p><p>Yacht brokerage is relationship-driven. A broker may work with other brokers, captains, yacht managers, shipyards, designers, surveyors, lawyers, insurers, financiers, marina operators, crew and previous clients. The person you speak to today may become tomorrow's client, listing source, referral, colleague or transaction partner. This is why reputation compounds.</p><p><b>Broker's insight</b></p><p><b>In a small industry, people remember how you made business feel.</b></p><p><b>The wrong way</b></p><p>A broker exaggerates information because they want the yacht to look attractive. They hide a concern because they fear losing the client. They promise an answer they do not have. They pressure the buyer because they want the deal. They repeat confidential information because it makes an interesting story. These behaviours may produce a short-term result. They damage long-term trust.</p><p><b>The professional way</b></p><p>A broker says: <em>\"I don't know yet. Let me verify that.\"</em> Or: <em>\"There is an issue we should investigate before you make a decision.\"</em> Or: <em>\"I understand why you like this yacht. Before we move forward, I want to make sure we have answered these three questions.\"</em></p><p>That is not weakness. That is professional confidence.</p>", "q": "A client tells you, \"I don't want anyone to know we're looking.\" What is the professional response?", "opts": ["Mention it to colleagues so they can help find a yacht", "Treat it as confidential and share it only if it is professionally justified and permitted", "Repeat it only if it makes a good story", "Ignore it, since the market already knows"], "correct": 1}, {"heading": "Chapter 5: Building the Client Profile", "body": "<p><b>Turn conversation into useful information</b></p><p>A broker needs a system for remembering and organising what the client tells them. Not every detail belongs in a formal database. But the broker should develop a clear working profile.</p><p><b>The client profile</b></p><p>&bull; <b>1. Background:</b> who is the client, and what is their experience with yachts?<br/>&bull; <b>2. Household:</b> who will use the yacht: family, friends, guests?<br/>&bull; <b>3. Usage:</b> how often, for how long, and where?<br/>&bull; <b>4. Lifestyle:</b> how do they want to spend their time aboard?<br/>&bull; <b>5. Preferences:</b> what do they like and dislike?<br/>&bull; <b>6. Requirements:</b> what characteristics are genuinely important?<br/>&bull; <b>7. Constraints:</b> budget, draft, crew, time, location?<br/>&bull; <b>8. Motivations:</b> why do they want a yacht?<br/>&bull; <b>9. Concerns:</b> what are they worried about?<br/>&bull; <b>10. Decision-making:</b> who is involved in the final decision?</p><p><b>Requirements vs preferences</b></p><p>A <b>requirement</b> is something the yacht probably must have. A <b>preference</b> is something the client would like.</p><p>&bull; Requirement: the yacht must accommodate the family comfortably. Preference: the client would prefer a beach club.<br/>&bull; Requirement: the yacht must be suitable for the intended cruising area. Preference: the client prefers a particular designer.</p><p>The distinction prevents the search from becoming unnecessarily narrow.</p><p><b>The client profile should evolve</b></p><p>Your first conversation will not reveal everything. A client may change their mind. They may discover new preferences after seeing yachts, realise that something they thought was essential is actually unimportant, or discover a new priority. This is normal. The profile is a living document.</p><p><b>Practical exercise</b></p><p>Build a one-page profile for this client:</p><p><em>James and Sophie are a couple with two children aged 9 and 12. They currently spend their summers in hotels around the Mediterranean. They want to start spending four to six weeks aboard a yacht each summer. They enjoy water sports, relaxed lunches and entertaining a small group of friends. They do not want the yacht to feel overly formal. They have never owned a yacht. James travels frequently for work and wants the ownership experience to be as straightforward as possible. Sophie is particularly concerned about privacy and family space. Their initial purchase budget is approximately €8 million.</em></p><p>Do not choose a yacht yet. You are building the client first.</p>", "q": "You are given the James and Sophie brief. What should you do first?", "opts": ["Shortlist yachts around €8 million", "Ask them to choose a builder", "Send them five listings to react to", "Build the client profile before choosing any yacht"], "correct": 3}, {"heading": "Exercise: The Client Profile: James and Sophie", "body": "<p><b>One-page client profile</b></p><p>Build a profile of James and Sophie covering users, experience, lifestyle, destinations, likely requirements, likely preferences, concerns, questions still unanswered and potential yacht characteristics.</p><p>Do not choose a yacht yet. You are building the client first.</p>", "exercise": {"intro": "Use only what the brief tells you. Where it doesn't say, put the gap under unanswered questions.", "groups": [{"title": "Who they are", "section": "services", "fields": [{"key": "jp_users", "label": "Users: who will be aboard?", "type": "long", "min": 20}, {"key": "jp_exp", "label": "Experience with yachts", "type": "long", "min": 20}, {"key": "jp_life", "label": "Lifestyle: how they want to spend time aboard", "type": "long", "min": 30}, {"key": "jp_dest", "label": "Destinations", "type": "long", "min": 15}]}, {"title": "What they need", "section": "services", "fields": [{"key": "jp_req", "label": "Likely requirements", "type": "long", "min": 30}, {"key": "jp_pref", "label": "Likely preferences", "type": "long", "min": 30}, {"key": "jp_conc", "label": "Concerns", "type": "long", "min": 30}]}, {"title": "What I still need to know", "section": "services", "fields": [{"key": "jp_unans", "label": "Questions still unanswered", "type": "long", "min": 30}, {"key": "jp_chars", "label": "Potential yacht characteristics (no yacht yet)", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 6: Your First Client", "body": "<p><b>Putting everything together</b></p><p>Imagine that the client has contacted you directly. They say:</p><p><em>\"We're thinking about buying our first yacht. We're not really sure what we need, but we'd like something around 35 metres.\"</em></p><p>A beginner might immediately send five listings. A broker starts a conversation.</p><p><b>Your first client conversation</b></p><p>Your objective is to discover enough information to understand who they are, how they want to use the yacht, what matters to them, what constraints exist, and what you still need to learn. Prepare your first conversation using these categories:</p><p>&bull; <b>Opening:</b> how will you make the client comfortable?<br/>&bull; <b>Background:</b> what would you like to know about their experience?<br/>&bull; <b>Lifestyle:</b> how do they imagine using the yacht?<br/>&bull; <b>People:</b> who will be aboard?<br/>&bull; <b>Destinations:</b> where do they want to cruise?<br/>&bull; <b>Preferences:</b> what have they seen or experienced that they liked?<br/>&bull; <b>Concerns:</b> what are they worried about?<br/>&bull; <b>Budget:</b> how would you approach this conversation professionally?<br/>&bull; <b>Next step:</b> what would you suggest doing after the first conversation?</p><p><b>Broker challenge</b></p><p>You have 15 minutes to conduct the discovery conversation. Your client will not give you everything immediately. You need to decide which questions matter most, when to ask follow-up questions, when to listen, when to clarify, when to summarise, and when to stop talking.</p><p>At the end, write a short <b>client brief</b> covering who the client is, why they want a yacht, how they expect to use it, their likely requirements, preferences, constraints and concerns, what remains unknown, and your proposed next step.</p><p><b>Broker's insight</b></p><p>A client should finish a first conversation feeling: <em>\"This person understood what I was trying to achieve.\"</em> Not: <em>\"This person showed me how much they know about yachts.\"</em></p><p><b>Knowledge creates credibility. Understanding creates trust.</b></p>", "q": "A new client writes: \"We'd like something around 35 metres, but we're not sure what we need.\" What does a broker do?", "opts": ["Start a discovery conversation rather than immediately sending listings", "Send five 35-metre listings", "Tell them to decide their needs first", "Quote typical prices for 35-metre yachts"], "correct": 0}, {"heading": "Exercise: Prepare Your First Conversation", "body": "<p><b>Preparing the conversation</b></p><p>Prepare your discovery conversation using these categories: opening, background, lifestyle, people, destinations, preferences, concerns, budget and next step. Write the questions or approach you would actually use.</p>", "exercise": {"intro": "Write the words you would actually use. Avoid yes/no questions.", "groups": [{"title": "My conversation plan", "section": "services", "fields": [{"key": "cv_open", "label": "Opening: how will you make the client comfortable?", "type": "long", "min": 30}, {"key": "cv_bg", "label": "Background: what would you like to know about their experience?", "type": "long", "min": 30}, {"key": "cv_life", "label": "Lifestyle: how do they imagine using the yacht?", "type": "long", "min": 30}, {"key": "cv_people", "label": "People: who will be aboard?", "type": "long", "min": 30}, {"key": "cv_dest", "label": "Destinations: where do they want to cruise?", "type": "long", "min": 30}, {"key": "cv_pref", "label": "Preferences: what have they seen or experienced that they liked?", "type": "long", "min": 30}, {"key": "cv_conc", "label": "Concerns: what are they worried about?", "type": "long", "min": 30}, {"key": "cv_budget", "label": "Budget: how would you approach this professionally?", "type": "long", "min": 30}, {"key": "cv_next", "label": "Next step: what would you suggest after the first conversation?", "type": "long", "min": 30}]}]}}, {"heading": "Professional Output: My First Client Brief", "body": "<p><b>My first client brief</b></p><p>After your (real or imagined) 15-minute discovery conversation, write a short <b>client brief.</b> Add your completed client profile and discovery exercise to your Broker Portfolio.</p><p>This becomes your first genuine example of client-facing brokerage thinking.</p>", "exercise": {"intro": "Write the brief as if a colleague will pick it up tomorrow.", "groups": [{"title": "The client brief", "section": "services", "fields": [{"key": "cb_who", "label": "1. Who the client is", "type": "long", "min": 30}, {"key": "cb_why", "label": "2. Why they want a yacht", "type": "long", "min": 30}, {"key": "cb_use", "label": "3. How they expect to use it", "type": "long", "min": 30}, {"key": "cb_req", "label": "4. Their likely requirements", "type": "long", "min": 30}, {"key": "cb_pref", "label": "5. Their preferences", "type": "long", "min": 30}, {"key": "cb_cons", "label": "6. Their constraints", "type": "long", "min": 30}, {"key": "cb_conc", "label": "7. Their concerns", "type": "long", "min": 30}, {"key": "cb_unk", "label": "8. What remains unknown", "type": "long", "min": 30}, {"key": "cb_next", "label": "9. Your proposed next step", "type": "long", "min": 30}]}, {"title": "Reflection on the conversation", "section": "profile", "fields": [{"key": "cb_reflect", "label": "What went well, what was hard, and what would you do differently?", "type": "long", "min": 60}]}]}}, {"heading": "Reflection and Broker's Notebook", "body": "<p><b>Reflection</b></p><p>This module is deliberately different from the previous two. You have spent less time looking at yachts and more time looking at people. These questions matter. You may discover that the people side of brokerage is exactly what attracts you, or that the technical or commercial side interests you more. Both are useful discoveries.</p><p><b>Broker's notebook</b></p><p>Before leaving this module, make sure you can explain:</p><p>&bull; first-time buyer<br/>&bull; experienced owner<br/>&bull; client motivation<br/>&bull; client requirement<br/>&bull; client preference<br/>&bull; client constraint<br/>&bull; discovery conversation<br/>&bull; active listening<br/>&bull; client profile<br/>&bull; discretion<br/>&bull; trust<br/>&bull; relationship capital<br/>&bull; client brief<br/>&bull; yacht-to-lifestyle translation</p>", "exercise": {"intro": "Answer honestly.", "groups": [{"title": "What I noticed", "section": "profile", "fields": [{"key": "rf_listen", "label": "Did I enjoy listening to the client?", "type": "short", "min": 10}, {"key": "rf_ask", "label": "Did I enjoy asking questions?", "type": "short", "min": 10}, {"key": "rf_person", "label": "Did I naturally want to understand the person?", "type": "short", "min": 10}, {"key": "rf_talk", "label": "Did I find it difficult to resist talking about yachts?", "type": "short", "min": 10}, {"key": "rf_translate", "label": "Did I enjoy turning lifestyle information into requirements?", "type": "short", "min": 10}, {"key": "rf_weekly", "label": "Would I enjoy having conversations like this every week?", "type": "short", "min": 10}, {"key": "rf_confid", "label": "Would I be comfortable hearing confidential information?", "type": "short", "min": 10}, {"key": "rf_patient", "label": "Could I remain patient when a client changes their mind?", "type": "short", "min": 10}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 4: final reflection</b></p><p>At the beginning of the academy, you learned to look at a yacht. Then you learned to look at the market. Now you have learned to look at the person. That sequence matters.</p><p>A yacht without a client is an asset. A client without a clear understanding of their needs is simply a collection of requirements. The broker connects the two.</p><p>The professional habit is:</p><p><b>Listen → Understand → Clarify → Translate → Compare → Advise.</b></p><p>Not: <em>Client asks → Broker sends listings.</em> The difference may look small. It is not. That difference is at the heart of professional brokerage.</p><p><b>What comes next</b></p><p>You understand the yacht. You understand the market. You are beginning to understand the client. Now we move inside the brokerage itself.</p><p><b>Module 5: Inside the Brokerage.</b> <em>What does the job really feel like?</em> You will discover what a broker actually does throughout a working week, where new business comes from, how brokers find yachts, how they evaluate opportunities, how they work with other brokers, what tools they use, and what happens behind the scenes before a yacht ever reaches a client.</p><p>Because understanding the client is only half the job. The next question is: <b>how does the broker actually make the business happen?</b></p>", "q": "What is the professional habit this module ends on?", "opts": ["Client asks, broker sends listings", "Compare, price, negotiate, close", "Listen, understand, clarify, translate, compare, then advise", "Present, persuade, pressure, sell"], "correct": 2}]$json$;
  v_final jsonb := $json$[{"q": "Why is there no \"typical\" yacht client?", "opts": ["Because all clients are entrepreneurs with similar goals", "Because clients rarely know what they want", "Because only experienced owners buy yachts", "Yacht clients have different backgrounds, experience levels, lifestyles, motivations and expectations"], "correct": 3}, {"q": "What is the difference between a requirement and a preference?", "opts": ["A requirement is something the yacht likely needs to provide; a preference is something the client would like but may compromise on", "A requirement is the client's budget; a preference is the yacht's price", "A preference must be met; a requirement is optional", "They mean the same thing"], "correct": 0}, {"q": "Why should a broker avoid talking too much in an initial client conversation?", "opts": ["Clients dislike hearing about yachts", "Talking reveals the broker's commission", "The first conversation is primarily about discovering the client's needs, not demonstrating the broker's knowledge", "Brokers should never share technical information"], "correct": 2}, {"q": "What are the five levels of listening?", "opts": ["Hearing, nodding, noting, replying and repeating", "What the client says, what they mean, what they value, what they fear, and what they have not considered", "What they want, what they can afford, what they will accept, what they will refuse and what they will sign", "Price, size, speed, age and builder"], "correct": 1}, {"q": "Why is it important to identify contradictions in a client's requirements?", "opts": ["They show the client is not serious", "They let the broker choose for the client", "They can safely be ignored until viewing", "Contradictions often reveal trade-offs or assumptions that need further exploration"], "correct": 3}, {"q": "What does discretion mean in a brokerage context?", "opts": ["Handling client information appropriately, protecting confidentiality and sharing it only when professionally justified and permitted", "Never discussing a client with anyone, including the client's own advisers", "Sharing information freely inside the brokerage", "Keeping quiet about problems with a yacht"], "correct": 0}, {"q": "Why should a client profile be treated as a living document?", "opts": ["Because it must be updated for legal reasons every month", "Because clients are usually dishonest at first", "Client needs can develop as they see yachts, learn more and reconsider their priorities", "Because the first profile is always wrong"], "correct": 2}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 4;
  if v_module is null then
    raise exception 'Yachts module 4 not found';
  end if;

  update public.academy_modules
     set title = 'The People & the Client', description = 'Yacht brokerage is a people business.'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
